// The protocol list `session` (the session section's two comments): 350 rows,
// 246 current and 104 replaced in the issue. The rule wording stays the issue
// snapshot's (`rules/protocol-session.md`); each entry re-extracts where the
// rule lives in 0.22 and what carries it:
//
//   - `protocol-session.md §11` plus the `SESS-*` ids that state the rule,
//     where the session specification is now the source;
//   - `guarantees.md §<section>` plus the register row, where the promise moved
//     into the guarantee register;
//   - a current design section (M1, network stack, value types, session tags,
//     event protocol, remote session, mount), where that design is still the
//     source — with no `SESS-*` anchor, since the session specification does
//     not cover it;
//   - `0.22 无此条`, where no current document states the rule at all (a
//     mechanism 0.19 or 0.22 deleted without a replacement rule).
//
// A row whose rule the session specification carries but no evidence backs is
// still `未验证`: the anchor says where the rule lives, the status says what
// proves it. Statuses are the re-check's and only move down.
